def score_valuation_v3(sd):
    """估值安全 — PE分位+市净率"""
    try:
        pe_pct = sd.get('pe_percentile', 50) or 50
        pb = sd.get('pb', 2) or 2
        if pe_pct < 0: return -1
        score = (100 - abs(pe_pct - 50)) * 0.1 + max(0, 5 - min(pb, 5))
        return max(0, min(10, score))
    except Exception: return 0

