def calculate_v3_total_score(stock_data, weights=None):
    """v4十维打分主函数（P0资金信号分层 + P1百分位归一化）。

    旧版 dict-based 接口。新代码请使用 ChaseHighScorer。
    """
    scorer = ChaseHighScorer()
    si = ScoreInput(stock_data=stock_data, weights=weights or DEFAULT_WEIGHTS)
    result = scorer.score(score_input=si)

    if weights is None:
        weights = DEFAULT_WEIGHTS

    ret = {
        "pass": result.passed, "filter_msg": result.filter_msg,
        "综合评分": int(result.score),
        "趋势结构": int(result.dimensions.get("趋势结构", 0)),
        "动量强度": int(result.dimensions.get("动量强度", 0)),
        "板块共振": int(result.dimensions.get("板块共振", 0)),
        "北向资金": int(result.dimensions.get("北向资金", 0)),
        "机构净买": int(result.dimensions.get("机构净买", 0)),
        "板块资金热度": int(result.dimensions.get("板块资金热度", 0)),
        "量价配合": int(result.dimensions.get("量价配合", 0)),
        "估值安全": int(result.dimensions.get("估值安全", 0)),
        "筹码稳定": int(result.dimensions.get("筹码稳定", 0)),
        "情绪热度": int(result.dimensions.get("情绪热度", 0)),
        "position_msg": result.position_msg,
        "_raw": result.raw,
    }
    return ret


