#  ChaseHighScorer — 新 Scorer 基类实现
# ═══════════════════════════════════════════════════

@register_scorer
class ChaseHighScorer(BaseScorer):
    """追高模型：十维评分（趋势/动量/板块共振/北向/机构/资金热度/量价/估值/筹码/情绪）"""

    model_name = "chase_high"

    def compute(self, si: ScoreInput) -> ScoreResult:
        sd = si.stock_data
        weights = si.weights or DEFAULT_WEIGHTS

        # 前置硬过滤
        pass_filter, filter_msg = hard_filter_v3(sd)
        if not pass_filter:
            return ScoreResult(
                score=0, passed=False, filter_msg=filter_msg,
                position_msg="前置淘汰",
                dimensions={k: 0 for k in DIM_NAMES},
                raw={k: 0 for k in RAW_KEYS},
            )

        # 十维打分
        s1 = score_trend_struct_v3(sd)
        s2 = score_momentum_v3(sd)
        s3 = score_sector_resonance_v3(sd)
        s4 = score_north_capital_v3(sd)
        s5 = score_inst_capital_v3(sd)
        s6 = score_sector_fund_heat_v3(sd)
        s7 = score_volume_price_v3(sd)
        s8 = score_valuation_v3(sd)
        s9 = score_chip_v3(sd)
        s10 = score_sentiment_v3(sd)

        def _safe(v):
            return 0 if v < 0 else v

        n1 = _safe(s1) / 25 * 100; n2 = _safe(s2) / 22 * 100
        n3 = _safe(s3) / 10 * 100; n4 = _safe(s4) / 10 * 100
        n5 = _safe(s5) / 10 * 100; n6 = _safe(s6) / 10 * 100
        n7 = _safe(s7) / 12 * 100; n8 = _safe(s8) / 10 * 100
        n9 = _safe(s9) / 7 * 100; n10 = _safe(s10) / 4 * 100

        total = int(
            n1 * weights.get("趋势结构", 15) / 100 +
            n2 * weights.get("动量强度", 18) / 100 +
            n3 * weights.get("板块共振", 8) / 100 +
            n4 * weights.get("北向资金", 15) / 100 +
            n5 * weights.get("机构净买", 10) / 100 +
            n6 * weights.get("板块资金热度", 5) / 100 +
            n7 * weights.get("量价配合", 14) / 100 +
            n8 * weights.get("估值安全", 3) / 100 +
            n9 * weights.get("筹码稳定", 6) / 100 +
            n10 * weights.get("情绪热度", 6) / 100
        )

        if total >= 85:
            pos_msg = "主线龙头，重仓60%~80%"
        elif total >= 70:
            pos_msg = "支线趋势，轻仓20%~40%"
        else:
            pos_msg = "分数不足70，放弃不参与"

        return ScoreResult(
            score=total, passed=True, filter_msg=filter_msg,
            position_msg=pos_msg,
            dimensions={
                "趋势结构": int(n1), "动量强度": int(n2), "板块共振": int(n3),
                "北向资金": int(n4), "机构净买": int(n5), "板块资金热度": int(n6),
                "量价配合": int(n7), "估值安全": int(n8), "筹码稳定": int(n9),
                "情绪热度": int(n10),
            },
            raw={"s1": s1, "s2": s2, "s3": s3, "s4": s4, "s5": s5,
                 "s6": s6, "s7": s7, "s8": s8, "s9": s9, "s10": s10},
        )


def _classify_signal(score, chg5, rsi, safety, mom):
    """信号分类（从 stock_screener_backup 恢复，供 get_simulated_stock_pool 和 app/renderers 使用）"""
    if score >= 70 and mom >= 65 and safety >= 55 and 30 <= rsi <= 70:
        return "强势买入", "badge-strong", "积极关注"
    if (score >= 55 and score < 70) or (rsi < 35 and score >= 45) or (safety >= 60 and mom >= 50):
        return "逢低吸纳", "badge-attention", "分批布局"
    if score < 40 or safety < 35 or rsi > 80:
        return "建议回避", "badge-watch", "谨慎对待"
    return "观望等待", "badge-hold", "等待信号"


DIM_NAMES = ["趋势结构", "动量强度", "板块共振", "北向资金", "机构净买",
             "板块资金热度", "量价配合", "估值安全", "筹码稳定", "情绪热度"]
RAW_KEYS = ["s1", "s2", "s3", "s4", "s5", "s6", "s7", "s8", "s9", "s10"]
